insert into public.grimoires(id,title,description,icon) values
('formas','Da forma ao desenho','Aprenda a construir objetos usando formas simples.','◯'),
('expressoes','Rostos que contam histórias','Construa expressões e uma personagem própria.','☺'),
('movimento','Gestos em movimento','Passe da linha de ação a uma pose expressiva.','➰'),
('perspectiva','Portas da perspectiva','Construa profundidade com horizontes e pontos de fuga.','▱'),
('luz','O feitiço da luz','Explore volumes, materiais e atmosferas com luz e sombra.','☀'),
('composicao','Histórias bem compostas','Aprenda a escolher o foco e organizar sua imagem.','▣') on conflict do nothing;
insert into public.challenges(id,title,prompt,category,difficulty,duration_minutes,xp,grimoire_id,step) values
(1000,'Guardião do lápis · Primeiros traços','Imagine uma pessoa guardiã que carrega um lápis maior que seu corpo. Use círculos e retângulos para montar a figura. Faça uma pose frontal simples e escolha uma expressão. Priorize o peso do lápis e o equilíbrio da pose. Você pode desenhar no papel ou no digital; o objetivo é praticar, não acertar de primeira.','Personagens','iniciante',5,25,null,null),
(1001,'Guardião do lápis · Estudo guiado','Imagine uma pessoa guardiã que carrega um lápis maior que seu corpo. Faça três esboços de gesto e escolha uma pose em três quartos. Desenhe mãos simplificadas, roupas e duas expressões alternativas. Priorize o peso do lápis e o equilíbrio da pose. Você pode desenhar no papel ou no digital; o objetivo é praticar, não acertar de primeira.','Personagens','intermediário',10,40,null,null),
(1002,'Guardião do lápis · Composição final','Imagine uma pessoa guardiã que carrega um lápis maior que seu corpo. Monte uma cena com a figura em movimento, um segundo elemento e uma fonte de luz. Trabalhe proporções, sobreposição e contraste de valores. Priorize o peso do lápis e o equilíbrio da pose. Você pode desenhar no papel ou no digital; o objetivo é praticar, não acertar de primeira.','Personagens','avançado',15,60,null,null),
